page = f"""<!DOCTYPE html>
<html lang="fr">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="robots" content="noindex,nofollow">
<title>Kare</title>
<script>(function(){{var d=document.documentElement,l=((navigator.languages&&navigator.languages[0])||navigator.language||'en').slice(0,2).toLowerCase()==='fr'?'fr':'en';d.classList.add('js');d.setAttribute('data-l',l);d.lang=l;}})();</script>
<style>
:root {{ --fond: #f4f4f6; --carte: #fff; --texte: #111; --doux: #666; --trait: #111; }}
@media (prefers-color-scheme: dark) {{ :root {{ --fond: #0d0d10; --carte: #18181c; --texte: #f2f2f2; --doux: #a8a8b0; --trait: #f2f2f2; }} }}
* {{ box-sizing: border-box; }}
body {{ margin: 0; background: var(--fond); color: var(--texte); font: 16px/1.5 -apple-system, BlinkMacSystemFont, "Helvetica Neue", sans-serif; }}
main {{ max-width: 760px; margin: 0 auto; padding: 40px 16px 64px; }}
h1 {{ font: 700 40px/1.1 "New York", Georgia, serif; margin: 0 0 4px; }}
.sous {{ color: var(--doux); margin: 0 0 32px; }}
h2 {{ font-size: 13px; letter-spacing: .12em; text-transform: uppercase; color: var(--doux); margin: 32px 0 10px; }}
.projets {{ display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 16px; }}
.carte {{ display: flex; flex-direction: column; gap: 6px; padding: 16px 18px; background: var(--carte); border: 2px solid var(--trait); box-shadow: 5px 5px 0 var(--trait); text-decoration: none; color: inherit; }}
.carte:hover {{ transform: translate(-1px, -1px); box-shadow: 6px 6px 0 var(--trait); }}
.carte {{ flex-direction: row; align-items: flex-start; gap: 14px; }}
.carte div {{ display: flex; flex-direction: column; gap: 6px; }}
.ico {{ flex: none; width: 52px; height: 52px; padding: 6px; border: 2.5px solid var(--trait); border-radius: 13px; background: var(--fond); }}
.carte b {{ font-size: 19px; }}
footer {{ margin-top: 40px; color: var(--doux); font-size: 13px; }}
.js [lang] {{ display: none; }}
.js[data-l="fr"] [lang="fr"], .js[data-l="en"] [lang="en"] {{ display: inline; }}
.js[data-l="fr"] .carte div > span[lang="fr"], .js[data-l="en"] .carte div > span[lang="en"] {{ display: block; }}
.js[data-l="fr"] .etat [lang="fr"], .js[data-l="en"] .etat [lang="en"] {{ display: inline; }}
.etat {{ align-self: flex-start; font-size: 11px; letter-spacing: .08em; text-transform: uppercase; border: 1.5px solid var(--trait); border-radius: 99px; padding: 1px 9px; }}
.etat.en-cours {{ background: var(--texte); color: var(--fond); }}
</style>
</head>
<body>
<main>
<div class="projets">{cartes}</div>
<footer>© 2026</footer>
</main>
</body>
</html>
"""
(ICI / "index.html").write_text(page)
print("✓ index.html")
